      const hasAnyStandingData = (this.standings || []).some(s => Number(s.wins || 0) !== 0 || Number(s.pointsFor || 0) !== 0 || Number(s.pointsAgainst || 0) !== 0 || Number(s.pointsDifferential || 0) !== 0);
      return !hasAnyFinalizedMatch && !hasAnyStandingData;
    }
    selectHistoryGroup(key) {
      this.selectedHistoryKey = key;
