      return groups;
    }
    latestGeneratedKnockoutStage(matches) {
      const order = ['PRE_QUARTERS', 'QUARTERS', 'SEMIFINALS', 'FINALS'];
      const generated = order.filter(stage => this.matchesForStage(matches, stage).length > 0);
      return generated.length ? generated[generated.length - 1] : '';
    }
    latestCompletedKnockoutStage(matches) {
      const order = ['PRE_QUARTERS', 'QUARTERS', 'SEMIFINALS', 'FINALS'];
      const completed = order.filter(stage => this.stageCompleted(matches, stage));
      return completed.length ? completed[completed.length - 1] : '';
    }
    stageCompleted(matches, stage) {
      const stageMatches = this.matchesForStage(matches, stage);
      return stageMatches.length > 0 && stageMatches.every(m => !!m.scoreFinalized);
    }
    matchesForStage(matches, stage) {
      return matches.filter(m => (m.roundType || '').toUpperCase() === stage).sort((a, b) => this.groupSort(a, b) || this.boardSort(a) - this.boardSort(b));
    }
    matchesForStageAndGroup(matches, stage, group) {
      return this.matchesForStage(matches, stage).filter(m => this.normalizedGroup(m.roundGroup) === group);
    }
    isKnockout(m) {
      return ['PRE_QUARTERS', 'QUARTERS', 'SEMIFINALS', 'FINALS'].includes((m.roundType || '').toUpperCase());
    }
    normalizedGroup(group) {
      return group && group.trim() ? group : 'Main';
    }
    groupSort(a, b) {
      return this.normalizedGroup(a.roundGroup).localeCompare(this.normalizedGroup(b.roundGroup));
    }
    boardSort(m) {
      const n = Number(m.boardNumber);
      return Number.isFinite(n) ? n : 999;
    }
    latestFinalizedSrrRound(matches) {
      const rounds = [...new Set(matches.filter(m => (m.roundType || 'SRR').toUpperCase() === 'SRR' && !!m.scoreFinalized).map(m => m.roundNumber || 0))];
      return rounds.length ? Math.max(...rounds) : 0;
    }
    matchRoundLabel(m) {
      return (m.roundType || 'SRR').toUpperCase() === 'SRR' ? `SRR ${m.roundNumber}` : this.stageDisplay(m.roundType || '');
    }
    roundGroupLabel(m) {
      const g = this.normalizedGroup(m.roundGroup);
      return g === 'Main' ? '' : `${g} -`;
    }
    stageDisplay(stage) {
      const s = (stage || '').toUpperCase();
      if (s === 'PRE_QUARTERS') return 'Pre-Quarter Finals';
      if (s === 'QUARTERS') return 'Quarter Finals';
      if (s === 'SEMIFINALS') return 'Semi Finals';
      if (s === 'FINALS') return 'Finals';
      return stage || 'Round';
    }
    winnerId(m) {
      return m.winnerId || '';
    }
    winnerName(m) {
      if (m.winnerId === m.player1Id) return m.player1Name || '';
      if (m.winnerId === m.player2Id) return m.player2Name || '';
      return '';
    }
    loserName(m) {
      if (m.winnerId === m.player1Id) return m.player2Name || '';
      if (m.winnerId === m.player2Id) return m.player1Name || '';
      return '';
    }
    winnerRank(m) {
      if (m.winnerId === m.player1Id) return m.player1Rank;
      if (m.winnerId === m.player2Id) return m.player2Rank;
      return undefined;
    }
    loserRank(m) {
      if (m.winnerId === m.player1Id) return m.player2Rank;
      if (m.winnerId === m.player2Id) return m.player1Rank;
      return undefined;
    }
    winnerScore(m) {
      return m.winnerId === m.player1Id ? m.player1Score || 0 : m.player2Score || 0;
    }
    loserScore(m) {
      return m.winnerId === m.player1Id ? m.player2Score || 0 : m.player1Score || 0;
    }
